class Solution {
    public int[] getStrongest(int[] arr,int k){
        Arrays.sort(arr);
        int median=arr[(arr.length-1)/2];
        Integer[] values=Arrays.stream(arr).boxed().toArray(Integer[]::new);
        Arrays.sort(values,(a,b)->{
            int strength=Integer.compare(Math.abs(b-median),Math.abs(a-median));
            return strength!=0?strength:Integer.compare(b,a);
        });
        int[] answer=new int[k];
        for(int i=0;i<k;i++)answer[i]=values[i];
        return answer;
    }
}

code.kotlin:
class Solution {
    fun getStrongest(arr:IntArray,k:Int):IntArray{
        arr.sort();
        val median=arr[(arr.size-1)/2];
        return arr.toList().sortedWith(compareByDescending<Int>{
            kotlin.math.abs(it-median)
        }.thenByDescending{
            it
        }).take(k).toIntArray()
    }
}

code.cpp:
class Solution {
    public: vector<int> getStrongest(vector<int>& arr,int k){
        sort(arr.begin(),arr.end());
        int median=arr[(arr.size()-1)/2];
        sort(arr.begin(),arr.end(),[&](int a,int b){
            int first=abs(a-median),second=abs(b-median);
            return first==second?a>b:first>second;
        });
        arr.resize(k);
        return arr;
    }
};
